package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The status asked for: OPEN, SETTLED, VOID, DELETED (a delete) or DRAFT (a restore). Publishes it with the user making the change and whether it is a review. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatus> status,
            Out<ChangedBy> changedBy, Out<ClaimReview> review, Out<VoidChoice> voidChoice) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String asked = request == null || request.status() == null ? "" : request.status().trim();
        ClaimStatus parsed;
        try {
            parsed = ClaimStatus.valueOf(asked);
        } catch (IllegalArgumentException e) {
            throw new BadRequestException("A status is OPEN, SETTLED or VOID");
        }
        if (parsed == ClaimStatus.PENDING) {
            throw new BadRequestException("A status is OPEN, SETTLED or VOID");
        }
        status.set(parsed);
        changedBy.set(by);
        boolean reviewing = request != null && Boolean.TRUE.equals(request.review());
        String reason = request == null || request.reason() == null ? "" : request.reason().trim();
        if (reviewing && (parsed == ClaimStatus.VOID || parsed == ClaimStatus.DELETED || parsed == ClaimStatus.DRAFT)) {
            throw new BadRequestException("A review approves (SETTLED) or rejects (OPEN) a claim");
        }
        if (reviewing && parsed == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new BadRequestException("A rejection needs a reason");
        }
        String voidReason = request == null || request.voidReason() == null ? "" : request.voidReason().trim();
        voidChoice.set(new VoidChoice(parsed == ClaimStatus.VOID && !voidReason.isEmpty() ? voidReason : null));
        review.set(reviewing ? new ClaimReview(true, parsed == ClaimStatus.OPEN ? reason : null) : ClaimReview.NONE);
    }
}
package net.officefloor.hq.app.claim;

/** Whether a status change is a steward's review of a PENDING claim (approve or reject), and a reject's reason. */
public record ClaimReview(boolean asked, String reason) {

    /** An open, settle or void: not a review. */
    public static final ClaimReview NONE = new ClaimReview(false, null);
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordClaimStatus {
    public void record(@Val Claim claim, @Val ClaimNumber number, @Val ChangedBy by, @Val ClaimReview review,
            PersonRepository people, WatchRepository watches, ClaimLogRepository logged, Audit audit, ClaimLog log) {
        String event = switch (claim.getStatus()) {
            case OPEN -> review.asked() ? "CLAIM_REJECTED" : "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> review.asked() ? "CLAIM_APPROVED" : "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DELETED -> "CLAIM_DELETED";
            case DRAFT -> "CLAIM_RESTORED";
        };
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String line = ClaimAudit.line(event, claim, by, person == null ? "" : person.getName(), number.value());
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        if (claim.getStatus() == ClaimStatus.VOID && claim.getSettledDue() != null) {
            line += " reversed=" + claim.getSettledDue().setScale(2).toPlainString();
        } else if (claim.getStatus() == ClaimStatus.VOID
                && logged.lastOn(claim.getSheetId(), claim.getId(), ClaimStatus.SETTLED) != null) {
            // A voided SETTLED claim settled without a figure (its due was n/a) reverses none.
            line += " reversed=n/a";
        }
        if (claim.getStatus() == ClaimStatus.OPEN && review.asked()) {
            line += " reason=" + review.reason();
        }
        if (claim.getStatus() == ClaimStatus.VOID && claim.getVoidReason() != null) {
            line += " reason=" + claim.getVoidReason();
        }
        audit.record(line);
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            ClaimNotify.watchers(claim, person, number.value(), by, watches, audit);
        }
        log.record(claim, by);
    }
}
